/* ═══════════════════════════════════════════════════════════════════════════
   gmt-brand.js — هوية الشركة: **مصدر واحد للوغو والاسم**  ·  2026-09-26
   ───────────────────────────────────────────────────────────────────────────
   سبب وجود هذا الملف (طلب المالك):
     «احقن هذه في كل النظام في كل مكان يحتاجها لأنو هي هي اللوغو تبع الشركة.
      أزل الشعارات التي تضعها أنت GMT لأنها عم تخرب أشكال.»

   المشكلة التي يحلّها جذرياً:
     كانت كل صفحة تكتب <img src="logo.jpg"> ومعها **بديل نصّي** مكتوب بخطّ عريض
     («GMT») يظهر إن لم تُرفع الصورة أو لم يُحلّ المسار. وهذا يحصل كثيراً:
       • أوراق الطباعة تُبنى داخل iframe بـsrcdoc ⇒ المسار النسبي قد لا يُحلّ.
       • صورة تُحوَّل بـhtml2canvas ⇒ تحميل الصورة قد لا يكتمل قبل اللقطة.
       • ملف يُنزَّل ويُفتح من الجوال ⇒ لا يوجد lib/ ولا logo.jpg بجانبه.
     في كل هذه الحالات كان يظهر «GMT» نصّاً فيخرّب الشكل.

   الحلّ: اللوغو **مضمَّن هنا base64** (15KB) ⇒ يعمل بلا شبكة وبلا مسار وبلا رفع،
   داخل الطباعة والصور المولّدة والملفات المنزّلة. ومعه حارس يستبدل أي بديل نصّي
   قديم باللوغو الحقيقي تلقائياً.
   ⚠️ عند تغيير اللوغو: بدّل الصورة هنا فقط — تتبدّل في كل النظام.
   ═══════════════════════════════════════════════════════════════════════════ */
(function (global) {
  'use strict';

  var LOGO = 'data:image/jpeg;base64,';

  /* ══ العلامة المائية — نسخة مبسّطة من الشعار للمطبوعات (2026-09-27) ══════
     طلب المالك: «نكتفي بكلمة كانون مع العدسة مع كلمة جنرال وتحتها ميديا تيك،
     أمّا الكتابات الصغيرة فما إلها داعي لأنّ حجمها راح يصير قريب من حجم الكتابة
     الفعلية في الفاتورة». وشفافيتها 4–7% **مشبعة في الملفّ نفسه** لا في CSS:
     `<img>` يُطبع دائماً، أمّا الخلفيات و`opacity` فقد تُسقطهما الطابعة
     (قاعدة OWN-PRINT-NO-BG). مُولَّدة بـ`توليد_علامة_مائية.py` — لا تُحرَّر بيد. */
  var WATERMARK = 'data:image/png;base64,';

  var BRAND = {
    logo    : LOGO,                    // يعمل في كل مكان — حتى بلا شبكة
    logoFile: 'logo.jpg',              // الملف المرفوع (أوضح وأكبر) — يُفضّل على الشاشة
    watermark: WATERMARK,              // علامة مائية مضمَّنة (~5.5% عتامة)
    nameAr  : 'مجموعة General Media Tech',
    nameEn  : 'General Media Tech',
    shortEn : 'GMT',
    tagline : 'Canon Authorized Dealer · Camera Solutions',

    /* وسم صورة جاهز — يجرّب الملف المرفوع ثم يسقط على المضمَّن (لا نصّ أبداً) */
    img: function (opts) {
      opts = opts || {};
      var cls = opts.cls ? ' class="' + opts.cls + '"' : '';
      var st  = opts.style || 'width:100%;height:100%;object-fit:contain;display:block';
      return '<img src="' + (opts.embed ? LOGO : BRAND.logoFile) + '" alt="' + BRAND.nameEn + '"' +
             cls + ' style="' + st + '" onerror="this.onerror=null;this.src=GMT_BRAND.logo">';
    },

    /* وسم العلامة المائية — يُوضع خلف المحتوى بلا أي تأثير على القراءة */
    wmImg: function (style) {
      return '<img src="' + WATERMARK + '" alt="" aria-hidden="true" ' +
             'style="' + (style || '') + '">';
    },

    /* وسم مضمَّن بالكامل — للطباعة والصور المولّدة والملفات المنزّلة */
    imgEmbed: function (style) {
      return '<img src="' + LOGO + '" alt="' + BRAND.nameEn + '" ' +
             'style="' + (style || 'width:100%;height:100%;object-fit:contain;display:block') + '">';
    }
  };

  global.GMT_BRAND = BRAND;

  /* ══ تحييد حاويات الشعار القديمة ══
     الحاويات (.logo وأخواتها) كانت مصمَّمة لنصّ «GMT» أبيض على خلفية حمراء مستديرة.
     لمّا صار داخلها اللوغو الحقيقي (مربّع بخلفية بيضاء) بقيت الخلفية الحمراء تحيط به
     فيبدو مقصوصاً وغريباً — وهو بالضبط «عم تخرب أشكال» الذي أبلغ عنه المالك.
     هذه القاعدة تُحيّد الحاوية **فقط عندما تحمل اللوغو**، ولا تمسّ أي حاوية أخرى. */
  try {
    if (!document.getElementById('gmt-brand-css')) {
      var st = document.createElement('style');
      st.id = 'gmt-brand-css';
      st.textContent =
        '[data-gmt-brand]{background:#fff!important;color:transparent!important;font-size:0!important;' +
        'padding:4px;overflow:hidden;box-sizing:border-box}' +
        '[data-gmt-brand] img{width:100%;height:100%;object-fit:contain;display:block}';
      (document.head || document.documentElement).appendChild(st);
    }
  } catch (_) {}

  /* ══ الحارس: يصلح ما هو موجود أصلاً في الصفحات بلا تعديل كل صفحة ══
     ① كل <img> شعار فشل تحميله ⇒ يُستبدل مصدره بالمضمَّن (لا بديل نصّي).
     ② أي عنصر بقي فيه نصّ «GMT» كشعار (.logo · .gmt-logo · .hd-gmt) ⇒ يُستبدل باللوغو.
     يعمل عند التحميل وبعده (السكربتات المتأخّرة تبني ترويساتها لاحقاً). */
  function fixLogos(root) {
    try {
      (root || document).querySelectorAll('img[src*="logo.jpg"],img[src*="logo.png"],img[alt="GMT"],img[alt="' + BRAND.nameEn + '"]')
        .forEach(function (im) {
          if (im.dataset.gmtBrand) return;
          im.dataset.gmtBrand = '1';
          im.addEventListener('error', function () { if (im.src !== LOGO) im.src = LOGO; });
          if (im.complete && im.naturalWidth === 0) im.src = LOGO;
        });
      /* بدائل نصّية قديمة — تُستبدل باللوغو الحقيقي */
      (root || document).querySelectorAll('.logo,.gmt-logo,.hd-gmt,.tb-logo,.login-logo,.picker-logo')
        .forEach(function (el) {
          if (el.dataset.gmtBrand) return;
          var txt = (el.textContent || '').trim();
          if (el.querySelector('img') || txt !== 'GMT') return;   // فيه صورة أصلاً ⇒ اتركه
          el.dataset.gmtBrand = '1';
          el.textContent = '';
          el.style.background = 'transparent';
          el.style.overflow = 'hidden';
          el.insertAdjacentHTML('beforeend', BRAND.img({ style: 'width:100%;height:100%;object-fit:contain;display:block' }));
        });
    } catch (_) {}
  }
  BRAND.fixLogos = fixLogos;

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { fixLogos(); });
  else fixLogos();
  [400, 1500, 4000].forEach(function (ms) { setTimeout(function () { fixLogos(); }, ms); });

})(typeof window !== 'undefined' ? window : this);
